INSERT INTO `groups` VALUES (1,'art4soul','password','Will Johns','','','Art for the Soul',3,5,0,'0000-01-01 10:00:00','0000-01-01 13:00:00',2.00,0.00,000,1,'The purpose is to provide a therapeutic outlet to process emotions, alleviate stress, unlock creativity, and foster growth beyond surface-level experiences. ','https://www.instagram.com/willjohns26/',0,1,1),(4,'deadly','password','Tonya Fedel &  Kymberley Williams','mdhs@mdhs.vic.gov.au','54610333','Deadly Catch-up',1,-1,3,'0000-01-01 10:00:00',NULL,2.00,0.00,000,1,'',NULL,0,1,1),(5,'dungeons_dragons','password','Tristan & Charlotte','manager@millhouse.org.au','54613185','Dungeons & Dragons',2,-1,0,'0000-01-01 13:00:00',NULL,2.00,0.00,000,1,'This a casual group is for anyone that enjoys playing table top games, including dungeons & dragons.',NULL,0,1,1),(7,'playgroup','password','Sarah Mclean','sarahmc@djerriwarrh.org','0422629249','Millhouse Playgroup',1,3,0,'0000-01-01 12:15:00','0000-01-01 11:00:00',1.50,0.00,000,0,'',NULL,0,1,1),(8,'parent_pathways','password','Sarah McLean','manager@millhouse.org.au','0422629249','Parent Pathways',1,-1,0,'0000-01-01 09:00:00',NULL,2.00,0.00,000,0,'This group allows parents select appropriate Service Australia support programs, with the help of a mentor.',NULL,0,1,1),(9,'u3a_writers','password','Deb Sealey','deb.sealey@hotmail.com','0491105356','U3A Writers',5,-1,1,'0000-01-01 10:00:00',NULL,2.00,0.00,000,1,'',NULL,0,1,1),(10,'u3a_photobooks','password','Deb Sealey','deb.sealey@hotmail.com','0491105356','U3A Digital Photobooks',2,-1,0,'0000-01-01 10:00:00',NULL,2.00,0.00,000,1,'',NULL,0,1,1),(11,'mental_health','password','Fred Smith','vmhpeers@outlook.comvmhpeers@outlook.com','0466577522','Peer Collective Mental Health',3,-1,0,'0000-01-01 14:00:00',NULL,2.00,0.00,000,0,'','',0,1,1),(12,'u3a_books','password','Deb Sealey','deb.sealey@hotmail.com','0491105356','U3A Book Club',2,-1,2,'0000-01-01 10:00:00',NULL,2.00,0.00,000,1,'','',0,1,1),(14,'stamps','password','Grey Loyer','','0354605008','Stamp Club',2,-1,2,'0000-01-01 20:00:00',NULL,2.00,0.00,000,1,'This group is for anyone with a passion for collecting coins and stamps. We can assist you with valuation of your collection. You can buy, sell & swap. We hold auctions and an annual fair.','',0,1,1),(15,'scrappers','password','Fred Smith','fred.smith@gmail.com','0455123456','Millhouse Scrappers',2,-1,0,'0000-01-01 10:00:00',NULL,2.00,0.00,001,1,'','',0,1,1),(16,'cafe','password','Sarah','manager@millhouse.org.au','54613185','Millhouse Cafe',2,-1,0,'0000-01-01 11:00:00',NULL,2.00,5.00,000,0,'','',0,1,1),(17,'feast','password','Sarah','manager@millhouse.org.au','54613185','Friday Feast',5,-1,0,'0000-01-01 12:00:00',NULL,2.00,5.00,001,0,'','',0,1,1),(19,'u3a_adult','password','Deb Sealey','deb.sealey@hotmail.com','0491105356','U3A Adult Learning',2,-1,4,'0000-01-01 11:00:00',NULL,1.50,0.00,000,1,'','',0,1,1),(20,'market','password','Sarah','manager@millhouse.org.au','54613185','Millhouse Market',4,-1,0,'0000-01-01 09:30:00',NULL,2.00,5.00,001,0,'For a small donation attendees can take home a basket full of grocery items.','',0,1,1),(21,'food_friends','password','Sarah McLean','manager@millhouse.org.au','54613185','Food with Friends',4,-1,0,'0000-01-01 10:00:00',NULL,2.00,10.00,000,0,'Cooking lessons for disabled kids.','',0,1,1),(22,'labour_party','password','Secretary','secretary@maryboroughlabor.com','','Australian Labour Party',4,-1,4,'0000-01-01 19:00:00',NULL,2.00,0.00,000,0,'','',0,1,1),(23,'theatre','password','Fred Smith','maryborough.theatre.company@gmail.com','','Maryborough Theatre Company',0,-1,0,'0000-01-01 13:00:00',NULL,2.00,0.00,000,0,'Maryborough Theatre Company provides a total theatre experience for all children and adults.','https://www.facebook.com/MaryboroughTheatreCompany/directory_intro',0,1,1),(24,'admin','password','Sarah McLean','manager@millhouse.org.au','0422629249','Administrator',-1,-1,-1,NULL,NULL,0.00,0.00,000,0,'Just to store the admin password.','',0,1,1),(25,'yarn','password','Sarah McLean, Rhonda or Ruth','XXXX@gmail,com','0000000000','Yarn Craft',5,-1,0,'0000-01-01 13:00:00',NULL,2.00,0.00,000,1,'XXXXXXX','',1,1,1),(27,'gamers','password','XXXX','XXXX@gmail.com','0000000000','Youth Activity Hub',3,-1,0,'0000-01-01 15:30:00',NULL,2.00,0.00,000,1,'XXXXXX','',0,1,1),(28,'axis_employment','password','Joel','reception@caei.com.au','1800 811 622','Axis Emplyment',2,4,0,'0000-01-01 09:00:00','0000-01-01 09:00:00',7.00,0.00,000,0,'At CAEI, we believe employment is more than a job - it is a pathway to independence, connection, and wellbeing.','https://www.facebook.com/axisemployment.caei/',0,1,1),(29,'are-able','password','Dianne','samhallam@areable.org.au','1800 566 066','are-able Employment',-1,-1,0,'0000-01-01 09:00:00','0000-01-01 09:00:00',7.00,0.00,000,0,'Do you have an illness, injury or disability? We’ll work with you, at your own pace, to help find a job you love.','https://www.facebook.com/areable.community',0,1,1),(30,'connecting_futures','password','Wayne Kelly','wayne@connectingfutures.com.au','0408493060','Conncting Futures',3,-1,0,'0000-01-01 10:00:00',NULL,6.00,0.00,000,0,'We work with NDIS participants via the School Leavers Employment Support service in to help them prepare for and find work opportunities. Our services are focused on a holistic approach, meaning we help build soft skills, technical skills and work with other professionals involved in supporting you towards your goals.','https://www.facebook.com/ConnectingFuturesLM/',0,1,1),(31,'apm','password','Wayne','apm4jobs@apm.net.au','1800 276 276','APM Employment Services',3,5,0,'0000-01-01 09:00:00',NULL,7.00,0.00,000,0,'Our purpose is enabling better lives. Our mission is to help people become more independent, feel like they belong, and get involved in their communities. With a team of over 16,000 caring professionals, we’re dedicated to this cause.','https://www.facebook.com/APMAustralia/',0,1,1),(32,'massage','password','Neil','manager@millhouse.org.au','0436287447','Remedial Massage (by appointment)',-1,-1,-1,'0000-01-01 09:00:00',NULL,10.00,0.00,000,0,'Hi, I’m Neil, I am a Remedial & Sports massage therapist working in Maryborough, Vic. I help people who may have had a long-term or chronic injury, brought on by overtraining in their fitness journey or the possibility of poor ergonomics in a work situation. I tend to use sports massage techniques combined with MFR (myofascial release) and deep tissue to help overcome those tight muscles which may cause dysfunction. ','https://www.facebook.com/maryboroughrsm/',0,1,1),(33,'canasta','password','Jen Fisher','manager@millhouse.org.au','54613185','Canasta',5,-1,-1,'0000-01-01 13:00:00',NULL,3.00,0.00,000,1,'For anyone who wants to enjoy a social game of canasta.',NULL,0,1,1),(34,'peer_collective','password','Jen','manager@millhouse.org.au','54613185','Peer Collective Support Group',3,-1,0,'0000-01-01 13:00:00',NULL,4.00,0.00,000,1,'A friendly group meeting for a cuppa, a chat and mutual support. All welcome.',NULL,0,1,1);
